import { ObjectUrlCache } from './ObjectUrlCache';
/**
 * Main WebView Manager - Primary API for webview functionality
 */

import { IframeController } from './IframeController'
import { MessageBridge } from './MessageBridge'
import { CodeInjector } from './CodeInjector'
import { SecurityUtils } from './utils'
import {
  WebViewOptions,
  WebViewState,
  WebViewMessage,
  WebViewSize,
  WebViewPosition,
  WebViewEventType,
  WebViewEventCallback,
  MessageCallback,
  CodeInjectionResult,
  WebViewError,
  IframeLoadError,
  MessageTypes
} from './types'

/**
 * Interface for queued code injections
 */
interface QueuedInjection {
  code: string;
  options?: {
    sanitize?: boolean;
    allowEval?: boolean;
    allowFunction?: boolean;
    timeout?: number;
  };
  resolve: (result: CodeInjectionResult) => void;
  reject: (error: Error) => void;
}

export class WebViewManager {
  private iframeController: IframeController
  private messageBridge: MessageBridge
  private codeInjector: CodeInjector
  private eventListeners = new Map<WebViewEventType, Set<Function>>()

  private generation = 0;
  private resourceGeneration = 0;
  private resourcesSuspended = false;
  private resourceUrls = new ObjectUrlCache();
  retainResourceUrls(urls: string[]): void { this.resourceGeneration++; this.resourcesSuspended = true; this.resourceUrls.retain(urls); }
  invalidateResourceUrls(): void { if (this.resourcesSuspended) this.resourceUrls.clear(); else this.resourceUrls.invalidate(); }

  // Code injection queue
  private injectionQueue: QueuedInjection[] = []
  private injectionGeneration = 0
  private isProcessingInjection = false

  private state: WebViewState = {
    isOpen: false,
    currentUrl: null,
    isLoading: false,
    hasError: false,
    lastError: null,
    lastActivity: 0
  }

  private options: Required<WebViewOptions> = {
    transparent: true,
    allowScripts: true,
    trustedOrigins: [],
    autoResize: true,
    debugMode: false,
    timeout: 10000,
    zIndex: 9999,
    cssClasses: [],
    enablePointerEvents: true,
    sandbox: 'allow-scripts allow-same-origin allow-forms allow-popups'
  }

  constructor(options: WebViewOptions = {}) {
    this.options = { ...this.options, ...options }

    // Initialize components
    this.iframeController = new IframeController(this.options.debugMode)
    this.messageBridge = new MessageBridge({
      debugMode: this.options.debugMode,
      enableQueue: true,
      maxQueueSize: 100,
      defaultTimeout: this.options.timeout
    })
    this.codeInjector = new CodeInjector(this.options.debugMode)

    // Setup emergency exit callback
    this.iframeController.setEmergencyExitCallback(() => {
      this.log('Emergency exit activated - closing webview')
      this.close()
    })

    // Setup message bridge listeners
    this.log('WebViewManager initialized with options:', this.options)
  }

  /**
   * Centralized iframe setup with proper load handling
   */
  private async setupIframeWithLoadHandling(
    iframe: HTMLIFrameElement,
    url: string,
    options?: {
      timeout?: number
      skipBootstrap?: boolean
    }
  ): Promise<void> {
    // IframeController has already awaited the actual navigation load event.
    // Waiting a second time here used to add a 5-second forced-success timeout.
    this.messageBridge.destroy();
    this.messageBridge.initialize(iframe);
    this.codeInjector.destroy();
    this.codeInjector.initialize(iframe);
    if (this.options.autoResize) this.iframeController.setupAutoResize(size => this.emit('resize', size));
    this.updateState({ isOpen: true, isLoading: false, currentUrl: url, lastActivity: Date.now() });
    this.setupMessageBridge();
    this.emit('load', url);
  }

  /**
   * Common iframe creation and setup
   */
  private async createAndSetupIframe(
    createIframeFunction: () => Promise<HTMLIFrameElement>,
    url: string,
    options?: {
      timeout?: number
      skipBootstrap?: boolean
    }
  ): Promise<void> {
    this.close();
    const generation = ++this.generation;
    try {
      this.updateState({ isLoading: true, hasError: false, lastError: null, currentUrl: url });
      this.emit('open', url);
      const iframe = await createIframeFunction();
      if (generation !== this.generation) throw new WebViewError('Navigation cancelled', 'SETUP_CANCELLED');
      await this.setupIframeWithLoadHandling(iframe, url, options);
    } catch (error) {
      if (generation === this.generation) {
        this.iframeController.destroy();
        this.updateState({ isOpen: false, isLoading: false, hasError: true, lastError: String(error) });
        this.emit('error', error instanceof Error ? error : new WebViewError(String(error), 'SETUP_ERROR'));
      }
      throw error;
    }
  }

  /**
   * Open webview with specified URL
   */
  async open(url: string): Promise<void> {
    return this.createAndSetupIframe(
      () => this.iframeController.create({
        url,
        transparent: this.options.transparent,
        zIndex: this.options.zIndex,
        cssClasses: this.options.cssClasses,
        sandbox: this.options.sandbox,
        enablePointerEvents: this.options.enablePointerEvents
      }),
      url
    );
  }

  /**
   * Open webview with HTML content
   */
  async openHtml(html: string, options?: {
    useSrcDoc?: boolean;
    basePath?: string;
    autoShow?: boolean;  // Control whether to show iframe automatically after load
  }): Promise<void> {
    const useSrcDoc = options?.useSrcDoc ?? true;
    const autoShow = options?.autoShow ?? true;

    if (useSrcDoc) {
      return this.openHtmlWithSrcDoc(html, autoShow);
    } else {
      return this.openHtmlWithBlobUrl(html, options?.basePath);
    }
  }

  /**
   * Open HTML using srcdoc (recommended for most cases)
   */
  private async openHtmlWithSrcDoc(html: string, autoShow: boolean = true): Promise<void> {
    return this.createAndSetupIframe(
      () => this.iframeController.createWithSrcDoc({
        srcdoc: html,
        transparent: this.options.transparent,
        zIndex: this.options.zIndex,
        cssClasses: this.options.cssClasses,
        sandbox: this.options.sandbox,
        enablePointerEvents: this.options.enablePointerEvents,
        autoShow: autoShow
      }),
      'srcdoc:html'
    );
  }

  /**
   * Open HTML using Blob URL (for special cases)
   */
  private async openHtmlWithBlobUrl(html: string, basePath?: string): Promise<void> {
    // Process HTML paths if basePath provided
    let processedHtml = html;
    if (basePath) {
      processedHtml = this.preprocessHtmlPaths(html, basePath);
    }

    // Create blob URL
    const htmlBlob = new Blob([processedHtml], { type: 'text/html;charset=utf-8' });
    const blobUrl = URL.createObjectURL(htmlBlob);

    try {
      await this.createAndSetupIframe(
        () => this.iframeController.create({
          url: blobUrl,
          transparent: this.options.transparent,
          zIndex: this.options.zIndex,
          cssClasses: this.options.cssClasses,
          sandbox: this.options.sandbox,
          enablePointerEvents: this.options.enablePointerEvents
        }),
        blobUrl
      );
    } finally {
      // Clean up blob URL
      setTimeout(() => {
        URL.revokeObjectURL(blobUrl);
        this.log('Blob URL cleaned up');
      }, 1000);
    }
  }

  /**
   * Обрабатываем относительные пути в HTML для Blob URL
   */
  private preprocessHtmlPaths(html: string, basePath: string): string {
    return html
      .replace(/src="(?!https?:\/\/|data:|blob:)([^"]+)"/g,
               `src="${basePath}$1"`)
      .replace(/href="(?!https?:\/\/|#|data:|blob:)([^"]+)"/g,
               `href="${basePath}$1"`)
      .replace(/url\(["']?(?!https?:\/\/|data:|blob:)([^"')]+)["']?\)/g,
               `url("${basePath}$1")`);
  }

  /**
   * Close webview
   */
  close(): void {
    this.log('Closing webview')

    const wasOpen = this.state.isOpen || this.state.isLoading;
    this.generation++;

    // Clear injection queue
    this.clearInjectionQueue()

    // Clean up components
    this.iframeController.destroy()
    this.messageBridge.destroy()
    this.codeInjector.destroy()

    this.updateState({
      isOpen: false,
      currentUrl: null,
      isLoading: false,
      hasError: false,
      lastError: null
    })

    this.resourceGeneration++; this.resourcesSuspended = false; this.resourceUrls.clear();
    if (wasOpen) this.emit('close')
    this.log('WebView closed')
  }

  /**
   * Reload current webview
   */
  async reload(): Promise<void> {
    if (!this.state.isOpen || !this.state.currentUrl) {
      throw new WebViewError('No webview to reload', 'RELOAD_ERROR')
    }

    this.log('Reloading webview')

    const generation = ++this.generation;
    try {
      this.updateState({ isLoading: true })
      await this.iframeController.reload()

      if (generation !== this.generation) throw new WebViewError('Navigation cancelled', 'SETUP_CANCELLED');
      // The controller has already awaited the actual navigation.
      const iframe = this.iframeController.getIframe()
      if (iframe) {
        await this.setupIframeWithLoadHandling(iframe, this.state.currentUrl, { skipBootstrap: true })
      }
    } catch (error) {
      if (generation === this.generation) this.updateState({
        isLoading: false,
        hasError: true,
        lastError: error instanceof Error ? error.message : String(error)
      })
      throw error
    }
  }

  /**
   * Navigate to new URL
   */
  async navigate(url: string): Promise<void> {
    this.log('Navigating to URL:', url)

    if (!this.state.isOpen) {
      throw new WebViewError('WebView not open', 'NAVIGATE_ERROR')
    }

    const generation = ++this.generation;
    try {
      this.updateState({ isLoading: true, currentUrl: url })
      await this.iframeController.navigate(url)

      if (generation !== this.generation) throw new WebViewError('Navigation cancelled', 'SETUP_CANCELLED');
      // The controller has already awaited the actual navigation.
      const iframe = this.iframeController.getIframe()
      if (iframe) {
        await this.setupIframeWithLoadHandling(iframe, url, { skipBootstrap: true })
      }
    } catch (error) {
      if (generation === this.generation) this.updateState({
        isLoading: false,
        hasError: true,
        lastError: error instanceof Error ? error.message : String(error)
      })
      throw error
    }
  }

  /**
   * Check if webview is open
   */
  isOpen(): boolean {
    return this.state.isOpen
  }

  /**
   * Get current webview state
   */
  getState(): WebViewState {
    return { ...this.state }
  }

  /**
   * Get iframe element
   */
  getIframe(): HTMLIFrameElement | null {
    return this.iframeController.getIframe()
  }

  /**
   * Send message to webview
   */
  async sendMessage(message: any): Promise<void> {
    if (!this.state.isOpen) {
      return Promise.resolve();
    }

    this.log('Sending message:', message)

    // Unity WebGL: Convert image file paths to blob URLs before sending
    const control = typeof message === 'string' ? (() => { try { return JSON.parse(message); } catch { return null; } })() : message;
    if (control?.type === 'loadView') this.resourcesSuspended = false;
    if (this.resourcesSuspended && (control?.type === 'response' || control?.type === 'batch-response')) return;
    const resourceGeneration = this.resourceGeneration;
    const generation = this.generation;
    const convertedMessage = await this.convertImagePathsInMessage(message);
    if (generation !== this.generation || resourceGeneration !== this.resourceGeneration) return;

    const webviewMessage: Partial<WebViewMessage> = {
      type: typeof convertedMessage === 'object' && convertedMessage.type ? convertedMessage.type : MessageTypes.USER_DATA,
      payload: convertedMessage,
      timestamp: Date.now()
    }

    try {
      await this.messageBridge.sendMessage(webviewMessage)
      this.updateState({ lastActivity: Date.now() })
    } catch (error) {
      this.log('Failed to send message:', error)
      throw error
    }
  }

  /**
   * Send message and wait for response
   */
  async sendMessageWithResponse<T = any>(message: any, timeout?: number): Promise<T> {
    if (!this.state.isOpen) {
      return Promise.reject(new WebViewError('WebView not open...', 'SEND_MESSAGE_ERROR'))
    }

    const webviewMessage: Partial<WebViewMessage> = {
      type: typeof message === 'object' && message.type ? message.type : MessageTypes.USER_DATA,
      payload: message,
      timestamp: Date.now()
    }

    try {
      const response = await this.messageBridge.sendMessageWithResponse<T>(webviewMessage, timeout)
      this.updateState({ lastActivity: Date.now() })
      return response
    } catch (error) {
      this.log('Failed to send message with response:', error)
      throw error
    }
  }

  /**
   * Add message listener
   */
  onMessage(callback: MessageCallback): void {
    this.messageBridge.onMessage(callback)
  }

  /**
   * Remove message listener
   */
  removeMessageListener(callback: MessageCallback): void {
    this.messageBridge.removeMessageListener(callback)
  }

  /**
   * Inject JavaScript code (with sequential queue)
   */
  async injectCode(code: string, options?: {
    sanitize?: boolean
    allowEval?: boolean
    allowFunction?: boolean
    timeout?: number
  }): Promise<CodeInjectionResult> {
    if (!this.state.isOpen) {
      throw new WebViewError('WebView not open', 'INJECT_CODE_ERROR')
    }

    if (!this.options.allowScripts) {
      throw new WebViewError('Script injection disabled', 'INJECT_CODE_ERROR')
    }

    // Create promise for this injection and add to queue
    return new Promise<CodeInjectionResult>((resolve, reject) => {
      this.injectionQueue.push({
        code,
        options,
        resolve,
        reject
      })

      // Start processing queue
      this.processInjectionQueue()
    })
  }

  /**
   * Inject external script
   */
  async injectScript(scriptUrl: string, options?: {
    timeout?: number
    cache?: boolean
  }): Promise<CodeInjectionResult> {
    if (!this.state.isOpen) {
      throw new WebViewError('WebView not open', 'INJECT_SCRIPT_ERROR')
    }

    if (!this.options.allowScripts) {
      throw new WebViewError('Script injection disabled', 'INJECT_SCRIPT_ERROR')
    }

    this.log('Injecting script:', scriptUrl)

    try {
      const result = await this.codeInjector.injectScript(scriptUrl, options)
      this.updateState({ lastActivity: Date.now() })
      return result
    } catch (error) {
      this.log('Script injection failed:', error)
      throw error
    }
  }

  /**
   * Set webview size
   */
  setSize(width: number, height: number): void {
    if (!this.state.isOpen) {
      throw new WebViewError('WebView not open', 'SET_SIZE_ERROR')
    }

    this.iframeController.resize({ width, height })
    this.emit('resize', { width, height })
  }

  /**
   * Set webview position
   */
  setPosition(x: number, y: number): void {
    if (!this.state.isOpen) {
      throw new WebViewError('WebView not open', 'SET_POSITION_ERROR')
    }

    const size = this.iframeController.getDimensions() || { width: 800, height: 600 }
    this.iframeController.setPosition({ x, y, ...size })
  }

  /**
   * Set transparency
   */
  setTransparency(enabled: boolean): void {
    if (!this.state.isOpen) {
      throw new WebViewError('WebView not open', 'SET_TRANSPARENCY_ERROR')
    }

    this.iframeController.setTransparency(enabled)
    this.options.transparent = enabled
  }

  /**
   * Show webview
   */
  show(): void {
    if (!this.state.isOpen) {
      throw new WebViewError('WebView not open', 'SHOW_ERROR')
    }

    this.iframeController.show()
  }

  /**
   * Enable or disable the emergency exit button
   */
  setEmergencyExitEnabled(enabled: boolean): void {
    this.iframeController.setEmergencyExitEnabled(enabled)
  }

  /**
   * Hide webview
   */
  hide(): void {
    if (!this.state.isOpen) {
      throw new WebViewError('WebView not open', 'HIDE_ERROR')
    }

    this.iframeController.hide()
  }

  /**
   * Test connection with ping
   */
  async ping(): Promise<number> {
    if (!this.state.isOpen) {
      throw new WebViewError('WebView not open', 'PING_ERROR')
    }

    try {
      const latency = await this.messageBridge.ping()
      this.updateState({ lastActivity: Date.now() })
      return latency
    } catch (error) {
      this.log('Ping failed:', error)
      throw error
    }
  }

  /**
   * Get message statistics
   */
  getMessageStats() {
    return this.messageBridge.getStats()
  }

  /**
   * Add event listener
   */
  addEventListener<T extends WebViewEventType>(
    event: T,
    callback: WebViewEventCallback<T>
  ): void {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, new Set())
    }

    this.eventListeners.get(event)!.add(callback)
  }

  /**
   * Remove event listener
   */
  removeEventListener<T extends WebViewEventType>(
    event: T,
    callback: WebViewEventCallback<T>
  ): void {
    const listeners = this.eventListeners.get(event)
    if (listeners) {
      listeners.delete(callback)
    }
  }

  /**
   * Destroy webview manager
   */
  destroy(): void {
    this.log('Destroying WebViewManager')

    this.close();

    // Clear injection queue (backup)
    this.clearInjectionQueue()

    // Clear event listeners
    this.eventListeners.clear()
  }

  /**
   * Setup message bridge event handling
   */
  private setupMessageBridge(): void {
    this.messageBridge.onMessage((message: WebViewMessage) => {
      this.updateState({ lastActivity: Date.now() })
      this.emit('message', message)
    })

    this.messageBridge.onError((error, message) => {
      this.log('Message bridge error:', error, 'for message:', message)
      this.updateState({
        hasError: true,
        lastError: error.message
      })
      this.emit('error', error)
    })
  }

  /**
   * Update internal state
   */
  private updateState(updates: Partial<WebViewState>): void {
    this.state = { ...this.state, ...updates }
  }

  /**
   * Emit event to listeners
   */
  private emit<T extends WebViewEventType>(
    event: T,
    ...args: Parameters<WebViewEventCallback<T>>
  ): void {
    const listeners = this.eventListeners.get(event)
    if (listeners) {
      listeners.forEach(callback => {
        try {
          (callback as any)(...args)
        } catch (error) {
          this.log('Error in event callback:', error)
        }
      })
    }
  }

  /**
   * Process injection queue sequentially
   */
  private async processInjectionQueue(): Promise<void> {
    // If already processing or queue is empty, do nothing
    if (this.isProcessingInjection || this.injectionQueue.length === 0) {
      return
    }

    this.isProcessingInjection = true
    const generation = this.injectionGeneration;

    while (this.injectionQueue.length > 0 && generation === this.injectionGeneration) {
      const injection = this.injectionQueue.shift()!

      try {
        this.log('Processing queued injection:', injection.code.substring(0, 100) + '...')

        // Perform actual injection
        const result = await this.performCodeInjection(injection.code, injection.options)
        if (generation !== this.injectionGeneration) throw new WebViewError('WebView closed', 'INJECT_CODE_ERROR');

        // Update state
        this.updateState({ lastActivity: Date.now() })

        // Resolve promise
        injection.resolve(result)

      } catch (error) {
        this.log('Queued code injection failed:', error)
        injection.reject(error instanceof Error ? error : new WebViewError(String(error), 'INJECT_CODE_ERROR'))
      }

      // Small delay between injections for stability
      if (this.injectionQueue.length && generation === this.injectionGeneration) await this.delay(10)
    }

    if (generation === this.injectionGeneration) this.isProcessingInjection = false
  }

  /**
   * Perform actual code injection
   */
  private async performCodeInjection(code: string, options?: {
    sanitize?: boolean
    allowEval?: boolean
    allowFunction?: boolean
    timeout?: number
  }): Promise<CodeInjectionResult> {
    try {
      return await this.codeInjector.injectCode(code, options)
    } catch (error) {
      throw new WebViewError(`Code injection failed: ${error}`, 'INJECT_CODE_ERROR')
    }
  }

  /**
   * Utility for delay
   */
  private delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms))
  }

  /**
   * Clear injection queue
   */
  private clearInjectionQueue(): void {
    this.injectionGeneration++;
    // Reject all pending injections
    this.injectionQueue.forEach(injection => {
      injection.reject(new WebViewError('WebView closed', 'INJECT_CODE_ERROR'))
    })

    this.injectionQueue = []
    this.isProcessingInjection = false
  }

  /**
   * Get injection queue status (for debugging)
   */
  getInjectionQueueStatus(): {
    queueLength: number
    isProcessing: boolean
  } {
    return {
      queueLength: this.injectionQueue.length,
      isProcessing: this.isProcessingInjection
    }
  }

  /**
   * Debug logging
   */
  private log(...args: any[]): void {
    if (this.options.debugMode) {
      console.log('[WebViewManager]', ...args)
    }
  }

  /**
   * Unity WebGL specific: Check if we're running in Unity WebGL environment
   */
  private isUnityWebGL(): boolean {
    // Check if Emscripten FS is available (Unity WebGL uses Emscripten)
    return typeof (window as any).FS !== 'undefined';
  }

  /**
   * Unity WebGL specific: Check if a string is a file path
   */
  private isFilePath(str: string): boolean {
    if (typeof str !== 'string') {
      return false;
    }

    // Check for /idbfs/ paths (Emscripten virtual file system)
    if (str.includes('/idbfs/')) {
      return true;
    }

    // Check for image extensions
    return /\.(png|jpg|jpeg|gif|webp|svg)$/i.test(str);
  }

  /**
   * Unity WebGL specific: Convert file path to blob URL using Emscripten FS
   */
  private async filePathToBlobUrl(filePath: string): Promise<string> {
    // console.log('[Unity WebGL] filePathToBlobUrl START:', filePath);

    try {
      const FS = (window as any).FS;

      if (!FS) {
        console.warn('[Unity WebGL] FS not available, returning original path:', filePath);
        return filePath;
      }

      // console.log('[Unity WebGL] Reading file with FS.readFile:', filePath);

      const blobUrl = this.resourceUrls.get(filePath, () => {
        // Read file using Emscripten's FS
        const fileData = FS.readFile(filePath);

        if (!fileData) {
          console.warn('[Unity WebGL] Could not read file (no data):', filePath);
          return null;
        }

        // console.log('[Unity WebGL] File read successfully, size:', fileData.length, 'bytes');

        // Determine MIME type from extension
        const ext = filePath.split('.').pop()?.toLowerCase() || 'png';
        const mimeType =
          ext === 'jpg' || ext === 'jpeg' ? 'image/jpeg' :
          ext === 'png' ? 'image/png' :
          ext === 'gif' ? 'image/gif' :
          ext === 'webp' ? 'image/webp' :
          ext === 'svg' ? 'image/svg+xml' :
          'image/png';

        // console.log('[Unity WebGL] MIME type determined:', mimeType, 'for extension:', ext);

        // Create blob from file data
        const blob = new Blob([fileData], { type: mimeType });
        // console.log('[Unity WebGL] Blob created, size:', blob.size, 'type:', blob.type);

        return blob;
        // console.log('[Unity WebGL] ✅ Blob URL created successfully!');
        // console.log('[Unity WebGL]   Original:', filePath);
        // console.log('[Unity WebGL]   Blob URL:', blobUrl);
      });

      return blobUrl;

    } catch (error) {
      console.error('[Unity WebGL] ❌ Error creating blob URL:', error);
      console.error('[Unity WebGL] Error details:', error instanceof Error ? error.message : String(error));
      console.error('[Unity WebGL] Stack:', error instanceof Error ? error.stack : 'no stack');
      return filePath; // Return original on error
    }
  }

  /**
   * Unity WebGL specific: Convert image paths in message to blob URLs
   */
  private async convertImagePathsInMessage(message: any): Promise<any> {
    const generation = this.generation;
    const resourceGeneration = this.resourceGeneration;
    // console.log('[Unity WebGL] convertImagePathsInMessage called with:', typeof message);

    // Only run in Unity WebGL
    if (!this.isUnityWebGL()) {
      return message;
    }

    // console.log('[Unity WebGL] Unity WebGL detected, processing message...');

    try {
      // Parse message if it's a string
      const parsed = typeof message === 'string' ? JSON.parse(message) : message;
      // console.log('[Unity WebGL] Message parsed, type:', parsed.type, 'keys:', Object.keys(parsed));

      // Handle batch responses (action 11 = GetImageUrl)
      if (parsed.type === 'batch-response' && Array.isArray(parsed.responses)) {
        // console.log('[Unity WebGL] Processing batch-response with', parsed.responses.length, 'responses');

        for (let i = 0; i < parsed.responses.length; i++) {
          if (generation !== this.generation || resourceGeneration !== this.resourceGeneration) return message;
          const resp = parsed.responses[i];
          // console.log(`[Unity WebGL] Response[${i}] - action:`, resp.action, 'result:', resp.result);

          // Check if this is a GetImageUrl response (action 11)
          if (resp.action === 11 && resp.result && this.isFilePath(resp.result)) {
            // console.log(`[Unity WebGL] 🎯 Found GetImageUrl response[${i}], converting:`, resp.result);
            resp.result = await this.filePathToBlobUrl(resp.result);
            // console.log(`[Unity WebGL] Response[${i}] converted to:`, resp.result);
          }
        }

        // console.log('[Unity WebGL] Batch conversion complete');
        return parsed;
      }

      // Handle single response
      if (parsed.action === 11 && parsed.result && this.isFilePath(parsed.result)) {
        // console.log('[Unity WebGL] 🎯 Found single GetImageUrl response, converting:', parsed.result);
        parsed.result = await this.filePathToBlobUrl(parsed.result);
        // console.log('[Unity WebGL] Single response converted to:', parsed.result);
        return parsed;
      }

      // No conversion needed
      // console.log('[Unity WebGL] No conversion needed for this message');
      return parsed;

    } catch (error) {
      console.error('[Unity WebGL] ❌ Error converting image paths:', error);
      console.error('[Unity WebGL] Error details:', error instanceof Error ? error.message : String(error));
      return message; // Return original on error
    }
  }
}
