/**
 * Cross-frame message communication bridge
 */

import { SecurityUtils } from './utils'
import {
  WebViewMessage,
  WebViewMessageResponse,
  MessageCallback,
  MessageResponseCallback,
  MessageErrorCallback,
  MessageBridgeOptions,
  MessageFilter,
  MessageStats,
  MessageTypes,
  MessagePriority,
  MessageQueueItem,
  MessageError,
  SecurityError
} from './types'

export class MessageBridge {
  private iframe: HTMLIFrameElement | null = null
  private messageCallbacks = new Set<MessageCallback>()
  private cancelResponses = new Map<string, () => void>()
  private responseCallbacks = new Map<string, MessageResponseCallback>()
  private errorCallbacks = new Set<MessageErrorCallback>()
  private messageQueue: MessageQueueItem[] = []
  private messageFilter: MessageFilter | null = null
  private isReady = false
  private debugMode = false
  private stats: MessageStats = {
    messagesSent: 0,
    messagesReceived: 0,
    messagesFailed: 0,
    averageResponseTime: 0,
    queueSize: 0,
    lastActivity: 0
  }

  private options: Required<MessageBridgeOptions> = {
    enableQueue: true,
    maxQueueSize: 100,
    defaultTimeout: 5000,
    enableCompression: false,
    messageFilter: {},
    debugMode: false
  }

  constructor(options: MessageBridgeOptions = {}) {
    this.options = { ...this.options, ...options }
    this.debugMode = this.options.debugMode
    this.messageFilter = this.options.messageFilter || null

    this.log('MessageBridge initialized with options:', this.options)
  }

  /**
   * Initialize bridge with iframe reference
   */
  initialize(iframe: HTMLIFrameElement): void {
    this.iframe = iframe
    this.isReady = true
    this.log('MessageBridge initialized with iframe')

    this.setupMessageListener();
    this.processMessageQueue()
  }

  /**
   * Send message to iframe
   */
  sendMessage(message: Partial<WebViewMessage>, timeout?: number): Promise<void> {
    return new Promise((resolve, reject) => {
      try {
        const fullMessage = this.prepareMessage(message)

        // Apply message filter
        if (this.messageFilter && !SecurityUtils.applyMessageFilter(fullMessage, this.messageFilter)) {
          throw new MessageError('Message blocked by filter', { message: fullMessage })
        }

        // Queue message if not ready
        if (!this.isReady || !this.iframe) {
          if (this.options.enableQueue) {
            this.queueMessage(fullMessage)
            resolve()
          } else {
            reject(new MessageError('Bridge not ready and queuing disabled'))
          }
          return
        }

        // Send message
        this.performSend(fullMessage, timeout)
          .then(() => {
            this.stats.messagesSent++
            this.updateLastActivity()
            resolve()
          })
          .catch(reject)

      } catch (error) {
        this.stats.messagesFailed++
        this.handleError(error as Error, message as WebViewMessage)
        reject(error)
      }
    })
  }

  /**
   * Send message and wait for response
   */
  sendMessageWithResponse<T = any>(
    message: Partial<WebViewMessage>,
    timeout?: number
  ): Promise<T> {
    return new Promise((resolve, reject) => {
      const messageTimeout = timeout || this.options.defaultTimeout
      const fullMessage = this.prepareMessage({
        ...message,
        expectsResponse: true,
        responseTimeout: messageTimeout
      })

      const finish = (error?: Error, value?: T) => {
        if (!this.cancelResponses.has(fullMessage.id!)) return;
        clearTimeout(timeoutId);
        this.cancelResponses.delete(fullMessage.id!);
        this.responseCallbacks.delete(fullMessage.id!);
        if (error) reject(error); else resolve(value as T);
      };
      const timeoutId = setTimeout(() => finish(new MessageError(`Response timeout after ${messageTimeout}ms`)), messageTimeout);
      this.cancelResponses.set(fullMessage.id!, () => finish(new MessageError('WebView closed')));
      this.responseCallbacks.set(fullMessage.id!, response => {
        if (response.type === 'success') finish(undefined, response.data);
        else finish(new MessageError(response.error || 'Unknown error'));
      });
      this.sendMessage(fullMessage).catch(error => finish(error));
    })
  }

  /**
   * Add message callback
   */
  onMessage(callback: MessageCallback): void {
    this.messageCallbacks.add(callback)
    this.log('Message callback added, total callbacks:', this.messageCallbacks.size)
  }

  /**
   * Remove message callback
   */
  removeMessageListener(callback: MessageCallback): void {
    this.messageCallbacks.delete(callback)
    this.log('Message callback removed, remaining callbacks:', this.messageCallbacks.size)
  }

  /**
   * Add error callback
   */
  onError(callback: MessageErrorCallback): void {
    this.errorCallbacks.add(callback)
  }

  /**
   * Remove error callback
   */
  removeErrorListener(callback: MessageErrorCallback): void {
    this.errorCallbacks.delete(callback)
  }

  /**
   * Set message filter
   */
  setMessageFilter(filter: MessageFilter): void {
    this.messageFilter = filter
    this.log('Message filter updated:', filter)
  }

  /**
   * Clear message filter
   */
  clearMessageFilter(): void {
    this.messageFilter = null
    this.log('Message filter cleared')
  }

  /**
   * Get message statistics
   */
  getStats(): MessageStats {
    return {
      ...this.stats,
      queueSize: this.messageQueue.length
    }
  }

  /**
   * Clear message queue
   */
  clearQueue(): void {
    this.messageQueue = []
    this.log('Message queue cleared')
  }

  /**
   * Check if bridge is ready
   */
  isConnected(): boolean {
    return this.isReady && this.iframe !== null
  }

  /**
   * Destroy bridge and clean up
   */
  destroy(): void {
    this.log('Destroying MessageBridge')

    // Clear listeners
    if (this.handleIncomingMessageInstance) {
      window.removeEventListener('message', this.handleIncomingMessageInstance)
      this.handleIncomingMessageInstance = undefined;
    }

    for (const cancel of Array.from(this.cancelResponses.values())) cancel();

    // Clear callbacks
    this.messageCallbacks.clear()
    this.responseCallbacks.clear()
    this.errorCallbacks.clear()

    // Clear queue
    this.messageQueue = []

    // Reset state
    this.iframe = null
    this.isReady = false
  }

  private handleIncomingMessageInstance?: (event: MessageEvent) => void;
  /**
   * Setup window message listener
   */
  private setupMessageListener(): void {
    if (this.handleIncomingMessageInstance)
      window.removeEventListener('message', this.handleIncomingMessageInstance);
    this.handleIncomingMessageInstance = this.handleIncomingMessage.bind(this);
    window.addEventListener('message', this.handleIncomingMessageInstance);
  }

  /**
   * Handle incoming messages from iframe
   */
  private handleIncomingMessage(event: MessageEvent): void {
    try {
      // Messages are now raw strings (no wrapper)
      // Try to parse the raw string
      let messageData: any;
      try {
        messageData = typeof event.data === 'string' ? JSON.parse(event.data) : event.data;
      } catch (e) {
        this.log('Failed to parse message:', event.data)
        return
      }

      this.log('Received message:', messageData)

      // For filter checking, we need a minimal WebViewMessage structure
      const messageForFilter: WebViewMessage = {
        type: messageData.type || 'unknown',
        payload: messageData,
        origin: event.origin,
        timestamp: Date.now()
      }

      // Apply message filter
      if (this.messageFilter && !SecurityUtils.applyMessageFilter(messageForFilter, this.messageFilter)) {
        this.log('Message blocked by filter:', messageData)
        return
      }

      // Check if this is a response to a previous message
      const messageType = messageData.type || '';
      if (messageType.endsWith(':response') || messageType.endsWith(':result')) {
        this.handleResponse(messageForFilter)
        return
      }

      // Update stats
      this.stats.messagesReceived++
      this.updateLastActivity()

      // Notify callbacks with RAW message data (not wrapped)
      this.messageCallbacks.forEach(callback => {
        try {
          callback(messageData)
        } catch (error) {
          this.log('Error in message callback:', error)
          this.handleError(error as Error, messageForFilter)
        }
      })

    } catch (error) {
      this.log('Error handling incoming message:', error)
      this.handleError(error as Error)
    }
  }

  /**
   * Handle message responses
   */
  private handleResponse(message: WebViewMessage): void {
    const messageId = message.payload?.messageId || message.id

    if (!messageId) {
      this.log('Response message missing message ID:', message)
      return
    }

    const callback = this.responseCallbacks.get(messageId)
    if (callback) {
      this.responseCallbacks.delete(messageId)

      const response: WebViewMessageResponse = {
        messageId,
        type: message.type.includes('error') ? 'error' : 'success',
        data: message.payload,
        error: message.type.includes('error') ? message.payload?.error : undefined,
        timestamp: Date.now()
      }

      callback(response)
    }
  }

  /**
   * Prepare message with required fields
   */
  private prepareMessage(message: Partial<WebViewMessage>): WebViewMessage {
    return {
      id: SecurityUtils.generateMessageId(),
      timestamp: Date.now(),
      priority: MessagePriority.NORMAL,
      payload: null, // Ensure payload is always present
      ...message,
      type: message.type || MessageTypes.USER_DATA
    }
  }

  /**
   * Perform actual message sending
   */
  private async performSend(message: WebViewMessage, timeout?: number): Promise<void> {
    if (!this.iframe || !this.isReady) {
      throw new MessageError('Bridge not ready for sending')
    }

    const targetWindow = this.iframe.contentWindow
    if (!targetWindow) {
      throw new MessageError('Cannot access iframe content window')
    }

    try {
      // Get target origin
      const targetOrigin = this.getTargetOrigin()

      this.log('Sending message:', message, 'to origin:', targetOrigin)

      // Send message
      targetWindow.postMessage(message, targetOrigin)

    } catch (error) {
      throw new MessageError('Failed to send message', { error, message })
    }
  }

  /**
   * Get target origin for postMessage
   */
  private getTargetOrigin(): string {
    if (!this.iframe) {
      return '*'
    }

    try {
      const url = new URL(this.iframe.src)
      return url.origin
    } catch (error) {
      this.log('Could not determine target origin, using wildcard')
      return '*'
    }
  }

  /**
   * Queue message for later sending
   */
  private queueMessage(message: WebViewMessage): void {
    if (this.messageQueue.length >= this.options.maxQueueSize) {
      // Remove oldest message
      this.messageQueue.shift()
      this.log('Message queue full, removed oldest message')
    }

    const queueItem: MessageQueueItem = {
      message,
      timestamp: Date.now(),
      retryCount: 0,
      maxRetries: 3
    }

    this.messageQueue.push(queueItem)
    this.log('Message queued, queue size:', this.messageQueue.length)
  }

  /**
   * Process queued messages
   */
  private async processMessageQueue(): Promise<void> {
    if (!this.isReady || this.messageQueue.length === 0) {
      return
    }

    this.log('Processing message queue, size:', this.messageQueue.length)

    const messages = [...this.messageQueue]
    this.messageQueue = []

    for (const item of messages) {
      try {
        await this.performSend(item.message)
        this.stats.messagesSent++
      } catch (error) {
        item.retryCount++

        if (item.retryCount < item.maxRetries) {
          // Re-queue for retry
          this.messageQueue.push(item)
          this.log('Message retry queued:', item.message.id, 'attempts:', item.retryCount)
        } else {
          this.stats.messagesFailed++
          this.log('Message failed after max retries:', item.message.id)
          this.handleError(error as Error, item.message)
        }
      }
    }

    this.updateLastActivity()
  }

  /**
   * Handle errors
   */
  private handleError(error: Error, message?: WebViewMessage): void {
    this.log('Error occurred:', error, 'for message:', message)

    this.errorCallbacks.forEach(callback => {
      try {
        callback(error, message)
      } catch (callbackError) {
        console.error('Error in error callback:', callbackError)
      }
    })
  }

  /**
   * Update last activity timestamp
   */
  private updateLastActivity(): void {
    this.stats.lastActivity = Date.now()
  }

  /**
   * Send ping message to test connection
   */
  async ping(): Promise<number> {
    const startTime = Date.now()

    try {
      await this.sendMessageWithResponse({
        type: MessageTypes.SYSTEM_PING
      })

      return Date.now() - startTime
    } catch (error) {
      throw new MessageError('Ping failed', { error })
    }
  }

  /**
   * Send system ready message
   */
  async sendReady(): Promise<void> {
    return this.sendMessage({
      type: MessageTypes.BRIDGE_READY,
      payload: {
        timestamp: Date.now(),
        version: '1.0.0'
      }
    })
  }

  /**
   * Debug logging
   */
  private log(...args: any[]): void {
    if (this.debugMode) {
      console.log('[MessageBridge]', ...args)
    }
  }
}
