/** Own every browser blob URL; retain only URLs still held by the bridge's bounded caches. */
export class ObjectUrlCache {
  private paths = new Map<string, string>();
  private urls = new Set<string>();
  get(path: string, load: () => Blob | null): string {
    const cached = this.paths.get(path);
    if (cached) return cached;
    const blob = load();
    if (!blob) return path;
    const url = URL.createObjectURL(blob);
    this.paths.set(path, url); this.urls.add(url);
    return url;
  }
  // New content may reuse the same path. Keep old URLs alive until the view clears.
  invalidate(): void { this.paths.clear(); }
  retain(values: string[]): void {
    const retained = new Set(values);
    for (const url of this.urls) if (!retained.has(url)) { URL.revokeObjectURL(url); this.urls.delete(url); }
    for (const [path, url] of this.paths) if (!this.urls.has(url)) this.paths.delete(path);
  }
  clear(): void { this.retain([]); }
  get size(): number { return this.urls.size; }
}
